252:             outputOptions(n, m_out);
253:             m_out << std::endl;
254:         }
255:     }
256:     else
257:     {
258:         std::stringstream strm;
259:         NL::json options;
260:         for (auto const& n : nv)
261:         {
262:             outputOptions(n, strm);
263:             NL::json j;
264:             try
265:             {
266:                 strm >> j;
267:             }
268:             catch (NL::json::parse_error&)
269:             {}
270:             options.push_back(j);
271:             strm.str("");
272:         }
273:         m_out << options;
274:     }
