278: void App::addArgs(ProgramArgs& args)
279: {
280:     args.add("command", "The PDAL command", m_command).setPositional();
281:     args.add("debug", "Sets the output level to 3 (option deprecated)",
282:         m_debug);
283:     args.add("verbose,v", "Sets the output level (0-8)", m_logLevel,
284:         LogLevel::None);
285:     args.add("drivers", "List available drivers", m_showDrivers);
286:     args.add("help,h", "Display help text", m_help);
287:     args.add("list-commands", "List available commands", m_showCommands);
288:     args.add("version", "Show program version", m_showVersion);
289:     args.add("options", "Show options for specified driver (or 'all')",
290:         m_showOptions);
291:     args.add("log", "Log filename (accepts stderr, stdout, stdlog, devnull"
292:         " as special cases)", m_log, "stderr");
293:     args.add("logtiming", "Turn on timing for log messages", m_logtiming);
294:     Arg& json = args.add("showjson", "List options or drivers as JSON output",
295:         m_showJSON);
296:     json.setHidden();
